playback/wave_player.crag.mlir:
// Wave Player
//
// A convenience wrapper around a crag.sampler that provides looping playback,
// start/stop gating, and end-of-file detection for audio wave files.
//
// The player reads from a sampler named "audio" and outputs a mono audio block
// each process() call.  Two events control gating:
//
//   start (void) — enable audio output (latch set)
//   stop  (void) — mute audio output  (latch reset)
//
// The player begins in the "playing" state (latch initialised to 1) so that
// audio flows immediately after a sampler asset is bound, without requiring
// an explicit start event.
//
// Looping:
//   When the `loop` parameter is ≥ 0.5 (i.e. treated as true), the read
//   position wraps modulo the bound asset length and crag.sample uses
//   per-sample modulo addressing so that blocks straddling the file boundary
//   are filled seamlessly from both the end and the beginning of the asset.
//   The result is gapless, click-free looping regardless of whether the asset
//   length is a multiple of the block size.
//
//   When `loop` < 0.5 the read position advances linearly and crag.sample
//   returns silence once the asset is exhausted — the natural end-of-file
//   condition.  The end-of-file is detected internally by comparing the
//   current frame position to the asset length; when it is reached the audio
//   output goes silent (no looping restart).
//
// Parameters:
//   loop  [0, 1]  — 1 = loop continuously, 0 = play once (default 1)
//
// Events:
//   start (void) — resume / un-mute playback
//   stop  (void) — pause / mute playback
//
// Sampler:
//   "audio" — bind a WAV file via crag_bind_audio_by_index(0, ptr, len)
//
// Output: !crag.audio<f32, 0, 1> — mono audio (or silence when muted / past end)
//
// Usage (after crag.include):
//   crag.include "standard-graphs/playback/wave_player.crag.mlir" as "wave_player"
//   ...
//   %audio = crag.subgraph_ref "wave_player"()
//                : () -> !crag.audio<f32, 0, 1>

module {
  crag.graph name = "wave_player" sample_rate = 0 channels = 1 {

    // -------------------------------------------------------------------------
    // Parameters
    // -------------------------------------------------------------------------
    %loop = crag.param "loop" min = 0.0 max = 1.0 default = 1.0 : f32

    // -------------------------------------------------------------------------
    // Events — start gates the output on, stop gates it off.
    // -------------------------------------------------------------------------
    %start_fired, %start_at = crag.event_void "start" : i1, i32
    %stop_fired,  %stop_at  = crag.event_void "stop"  : i1, i32

    // SR latch: set by "start", reset by "stop".
    // Initialised to 1 so playback begins immediately.
    %playing = crag.latch %start_fired, %stop_fired : i1, i1 -> i1
    %playing_f32 = arith.uitofp %playing : i1 to f32

    // -------------------------------------------------------------------------
    // Sampler
    // -------------------------------------------------------------------------
    %s   = crag.sampler "audio" : !crag.sampler<"audio">

    // Query the runtime asset length (in interleaved float samples).
    // Returns 0 when no asset is bound; we guard against zero-division below.
    %len = crag.sampler_length %s : !crag.sampler<"audio"> -> i64

    // -------------------------------------------------------------------------
    // Compute playback position
    // -------------------------------------------------------------------------
    %frame = crag.curframe : i64

    // Guard: replace a zero length with 1 to avoid division by zero.
    // (The resulting modulo is harmless because crag.sample will return silence
    // when no asset is bound regardless of the position.)
    %c0      = arith.constant 0   : i64
    %c1      = arith.constant 1   : i64
    %half    = arith.constant 0.5 : f32
    %len_ok  = arith.cmpi sgt, %len, %c0 : i64
    %safe_len = arith.select %len_ok, %len, %c1 : i64

    // Wrapped position for looping (block-aligned).
    %frame_mod = arith.remsi %frame, %safe_len : i64

    // Select between looping and one-shot position.
    %loop_on = arith.cmpf ogt, %loop, %half : f32
    %pos     = arith.select %loop_on, %frame_mod, %frame : i64

    // -------------------------------------------------------------------------
    // Read audio from the sampler
    // -------------------------------------------------------------------------
    // When looping, pass safe_len as the `end` argument so the lowering wraps
    // each sample index modulo the asset length, eliminating the silence gap
    // and skipped samples that would otherwise occur when a block straddles
    // the end of the audio file.  When not looping, pass 0 to keep the
    // existing behaviour of returning silence once the asset is exhausted.
    %wrap_len = arith.select %loop_on, %safe_len, %c0 : i64

    // Sampler output is pinned MONO (`<f32, 0, 1>`) rather than the
    // channel-agnostic `<f32, 0, 0>` placeholder.  Reason: the runtime audio
    // asset bound through `crag_bind_audio_by_index` is laid out as a flat,
    // interleaved-at-source-channels float buffer, and `crag.sample` reads
    // `blockSize * out_channels` consecutive samples starting at `pos`.  If
    // the output type were widened uniformly to the host engine's channel
    // count (e.g. 2 for a stereo engine), a mono wave file would be read at
    // *twice* the expected rate and re-interpreted as stereo interleaved —
    // producing playback at the wrong pitch with audible block-boundary
    // discontinuities, because `pos` advances by `blockSize` per block while
    // the sampler reads `2 * blockSize` samples (a 50%-overlap rewind every
    // block).  Pinning the interior to mono keeps `nSamp == blockSize` per
    // block (one source sample per output frame) and lets the engine's
    // `crag-inject-channel-mixers` pass upmix this mono signal to the host
    // channel count *at the wrapper boundary* — the same path
    // `mono_synth` / `random-wave` take.
    %audio_raw = crag.sample %s, %pos, %wrap_len
                     : !crag.sampler<"audio">, i64, i64
                       -> !crag.audio<f32, 0, 1>

    // -------------------------------------------------------------------------
    // Gate by playing state
    // -------------------------------------------------------------------------
    %audio = crag.scale %audio_raw, %playing_f32
                 : !crag.audio<f32, 0, 1>, f32 -> !crag.audio<f32, 0, 1>

    // -------------------------------------------------------------------------
    // Progress meter: normalized playback position [0, 1]
    // -------------------------------------------------------------------------
    %len_f32   = arith.sitofp %safe_len : i64 to f32
    %frame_f32 = arith.sitofp %frame_mod : i64 to f32
    %progress  = arith.divf %frame_f32, %len_f32 : f32
    crag.meter "progress" %progress min = 0.0 max = 1.0 : f32

    crag.output %audio : !crag.audio<f32, 0, 1>
  }
}

sequencing/beat_in_measure.crag.mlir:
// beat_in_measure crag.func — derive beat position within a measure
// (named-pin form).
//
// Takes the beat event produced by `metronome` plus a `beat_count` and
// `beats_per_measure` value, and republishes a beat event annotated with the
// 0-based beat position within the current measure.
//
// Named control pins (Phase 5 migration from the legacy
// `^bb0(i1, i32, i32, i32) -> (i1, i32, i32)` positional form — the operand and
// result types are unchanged, so call sites are identical):
//
//   Inputs:
//     beat               — (event_void) beat trigger from metronome: (fired, at)
//     beat_count         — (param_int, i32) total beats elapsed (0-indexed)
//     beats_per_measure  — (param_int, i32) beats per measure (e.g. 4 for 4/4)
//
//   Output (event_output_int, subtype "beat_position"):
//     beat_in_measure    — (fired, sample_offset, beat)
//       fired         — pass-through of the input fired flag
//       sample_offset — pass-through of the input beat offset
//       beat          — beat position in [0, beats_per_measure - 1]
//                       = beat_count % beats_per_measure
//
// Typical usage inside a graph (call site unchanged from the legacy form):
//   %f, %at = crag.func_ref "metronome"(%ref, %period) : (i32, i32) -> (i1, i32)
//   %f2, %at2, %beat = crag.func_ref "beat_in_measure"(%f, %at, %count, %bpm)
//       : (i1, i32, i32, i32) -> (i1, i32, i32)

module {
  crag.func name = "beat_in_measure" {
    %fired, %at        = crag.event_void "beat" subtype = "beat" : i1, i32
    %beat_count        = crag.param_int "beat_count"
                             min = 0 max = 1000000 default = 0 : i32
    %beats_per_measure = crag.param_int "beats_per_measure"
                             min = 1 max = 32 default = 4 : i32

    // beat = beat_count % beats_per_measure
    %beat = arith.remsi %beat_count, %beats_per_measure : i32

    crag.event_output_int "beat_in_measure" %fired, %at, %beat
        subtype = "beat_position" : i1, i32, i32
    crag.func_return
  }
}

sequencing/simple_amp_sequencer.crag.mli:
// Simple amplitude sequencer — applies beat-indexed gain steps to audio.
//
// Consumes a routed `beat` event from an upstream `conductor` (via the public
// `beat_input` event pin) and uses `beat_in_measure` to compute the beat
// position within a measure, then selects one of four gain values
// (gain_0..gain_3) to scale the audio input.  This creates a simple rhythmic
// amplitude pattern that cycles every `beats_per_measure` beats.
//
// Block arguments:
//   %audio_in — mono audio input to scale
//
// Control inputs (patchbay-routable):
//   beat_input        — (event_void, subtype "beat") upstream beat trigger;
//                       wire `conductor.beat` -> `simple_amp_sequencer.beat_input`
//
// Parameters:
//   bpm               — tempo in beats per minute (default 120)
//   beats_per_measure — time signature numerator (default 4)
//   gain_0            — gain for beat 0 (downbeat, default 1.0)
//   gain_1            — gain for beat 1 (default 0.5)
//   gain_2            — gain for beat 2 (default 0.75)
//   gain_3            — gain for beats 3+ (default 0.25)
//
// The gain selection uses a 4-step sequencer:
//   beat_in_measure == 0 → gain_0
//   beat_in_measure == 1 → gain_1
//   beat_in_measure == 2 → gain_2
//   beat_in_measure >= 3 → gain_3
//
// This graph no longer owns an internal metronome: there is a single
// authoritative timing source, the upstream conductor, routed in through
// `beat_input`.  `bpm` is retained because the beat *count* (and hence the
// beat-in-measure index that drives gain selection) is derived locally from
// `crag.curframe` and the beat period; patch the sequencer's `bpm` to match the
// conductor's tempo so the local count tracks the routed beats.
module {
  crag.include_func "sequencing/beat_in_measure.crag.mlir" as "beat_in_measure"

  crag.graph name = "simple_amp_sequencer" sample_rate = 0 channels = 1 {
  ^bb0(%audio_in: !crag.audio<f32, 0, 1>):
    %sr = crag.sample_rate : f32

    // Upstream beat input (patchbay-routed from conductor.beat). This is the
    // sequencer's beat trigger — there is no internal metronome.
    %beat_in_fired, %beat_in_at = crag.event_void "beat_input"
                             subtype = "beat" : i1, i32

    // Parameters
    %bpm               = crag.param "bpm"
                             min = 20.0 max = 300.0 default = 120.0
                             unit = "bpm" : f32
    %beats_per_measure = crag.param_int "beats_per_measure"
                             min = 1 max = 32 default = 4 : i32
    %gain_0            = crag.param "gain_0" min = 0.0 max = 2.0 default = 1.0   : f32
    %gain_1            = crag.param "gain_1" min = 0.0 max = 2.0 default = 0.5   : f32
    %gain_2            = crag.param "gain_2" min = 0.0 max = 2.0 default = 0.75  : f32
    %gain_3            = crag.param "gain_3" min = 0.0 max = 2.0 default = 0.25  : f32

    // Beat period in samples = sr * 60 / bpm (used to count elapsed beats)
    %sixty_f    = arith.constant 60.0 : f32
    %sr_x60     = arith.mulf %sr, %sixty_f : f32
    %period_f   = arith.divf %sr_x60, %bpm : f32
    %period_i64 = arith.fptosi %period_f : f32 to i64

    // Compute beat count = curframe / period (samples elapsed / period)
    %cur_frame  = crag.curframe : i64
    %count_i64  = arith.divsi %cur_frame, %period_i64 : i64
    %beat_count = arith.trunci %count_i64 : i64 to i32

    // Get beat position within the measure (0-indexed), driven by the routed
    // beat trigger (beat_input) rather than an internal metronome.
    %fired_b, %at_b, %beat = crag.func_ref "beat_in_measure"(
                                  %beat_in_fired, %beat_in_at, %beat_count,
                                  %beats_per_measure)
                                  : (i1, i32, i32, i32) -> (i1, i32, i32)

    // Select gain for the current beat-in-measure (4-step sequencer)
    %c0       = arith.constant 0 : i32
    %c1       = arith.constant 1 : i32
    %c2       = arith.constant 2 : i32
    %is_beat0 = arith.cmpi eq, %beat, %c0 : i32
    %is_beat1 = arith.cmpi eq, %beat, %c1 : i32
    %is_beat2 = arith.cmpi eq, %beat, %c2 : i32
    %gain_sel  = arith.select %is_beat2, %gain_2, %gain_3 : f32
    %gain_sel1 = arith.select %is_beat1, %gain_1, %gain_sel : f32
    %gain      = arith.select %is_beat0, %gain_0, %gain_sel1 : f32

    // Apply the selected gain to the audio input
    %out = crag.scale %audio_in, %gain
               : !crag.audio<f32, 0, 1>, f32 -> !crag.audio<f32, 0, 1>
    crag.output %out : !crag.audio<f32, 0, 1>
  }
}
